var i=`1116-chicago-deep-dish-pizza`;var t=`world-1116`;var s=`US`;var n=`northern-america`;var r=8;var o=130;var l={en:`Chicago Deep-Dish Pizza`,ua:`Чиказька глибока піца`};var u={en:`Chicago Deep-Dish Pizza is a dish from United States prepared with all-purpose flour, instant yeast, mozzarella, italian sausage. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Чиказька глибока піца, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: пшеничне борошно універсальне, інстантні дріжджі, моцарела, італійська ковбаса. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 70 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 70 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:70,i:[[`all-purpose-flour`,520,`g`],[`water`,315,`ml`],[`instant-yeast`,6,`g`],[`olive-oil`,60,`ml`],[`table-salt`,8,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:13,i:[]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:9,i:[[`mozzarella`,430,`g`],[`italian-sausage`,480,`g`],[`tomato-passata`,390,`g`],[`parmigiano-reggiano`,90,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 38 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 38 хвилин до готовності.`,t:[`baking`],m:38,i:[]}];var d={slug:i,id:t,country:`US`,region:n,servings:8,minutes:130,title:l,text:u,steps:g};export{s as country,d as default,t as id,o as minutes,n as region,r as servings,i as slug,g as steps,u as text,l as title};